export function getCountryDetails(countryName) {
  if (!countryName) return null;
  return COUNTRY_STATS[countryName] || {
    name: countryName,
    code: countryName.slice(0, 3).toUpperCase(),
    flag: "🌍",
    users: 1200,
    clips: 4800,
    tier: 1,
    label: "A few downloads",
    city: countryName
  };
}
